   $b=$a['journal']['record']['binding'];$q=['contract_version'=>'1.0.0','action'=>'AUTHORIZE','binding'=>$b,'context'=>['actor_id'=>1,'logical_reference'=>'inert-held-source','approval_reference'=>$b['approval_reference'],'authorization_revision'=>$b['authorization_revision'],'product_version'=>0,'expected_product_version'=>0],'evidence_references'=>[$f['plan_hash']],'duplicate_key'=>str_repeat('e',64),'data'=>[]];self::assertWPError(NativeBridge::connect('1.0.0')->exchange($q));self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());
   self::assertWPError(Evidence::resolve($f['scope'],1,$f['mapping_id']+100000,$f['spec_id'],$f['plan_hash']));self::assertWPError(Evidence::resolve($f['scope'],1,$f['mapping_id'],$f['spec_id'],str_repeat('f',64)));self::assertWPError(Evidence::register($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash'],str_repeat('f',64)));
   self::assertSame(1,$wpdb->update(Tables::product_versions(),['notes'=>'changed trusted source'],['id'=>$f['business_version_id']],['%s'],['%d']));self::assertWPError(Evidence::register($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash'],$r['evidence_hash']));WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());self::assertWPError(Evidence::resolve($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash']));
  }finally{remove_filter('pre_http_request',$deny,PHP_INT_MAX);}
